const cmds = [
  ["/Users/cooper/Projects/bundjil", "pwd; git rev-parse --show-toplevel; git rev-parse HEAD; git branch --show-current; git status --short; find .. -name AGENTS.md -print | head -20"],
  ["/Users/cooper/Projects/site", "pwd; git rev-parse --show-toplevel; git rev-parse HEAD; git branch --show-current; git status --short; find .. -name AGENTS.md -print | head -20"]
];
const out = await Promise.all(cmds.map(async ([workdir, cmd]) => ({workdir, result: await tools.exec_command({cmd, workdir, yield_time_ms:10000, max_output_tokens:12000})})));
for (const x of out) { text(`WORKDIR ${x.workdir}\n${x.result.output}`); }

const out = await Promise.all([
  tools.exec_command({cmd:"sed -n '1,260p' AGENTS.md","workdir":"/Users/cooper/Projects/bundjil","yield_time_ms":10000,"max_output_tokens":20000}),
  tools.exec_command({cmd:"sed -n '1,260p' AGENTS.md","workdir":"/Users/cooper/Projects/site","yield_time_ms":10000,"max_output_tokens":20000})
]); text("BUNDJIL AGENTS\n"+out[0].output+"\nSITE AGENTS\n"+out[1].output);

const out = await Promise.all([
  tools.exec_command({cmd:"rg -l -i --hidden --glob '!node_modules/**' --glob '!.git/**' --glob '!.alchemy/**' 'doppler|DOPPLER_TOKEN|secrets-fetch-action|service token' . | sort","workdir":"/Users/cooper/Projects/bundjil","yield_time_ms":10000,"max_output_tokens":20000}),
  tools.exec_command({cmd:"rg -l -i --hidden --glob '!node_modules/**' --glob '!.git/**' --glob '!.alchemy/**' 'doppler|DOPPLER_TOKEN|secrets-fetch-action|service token' . | sort","workdir":"/Users/cooper/Projects/site","yield_time_ms":10000,"max_output_tokens":30000})
]); text("BUNDJIL\n"+out[0].output+"\nSITE\n"+out[1].output);

const out = await Promise.all([
  tools.exec_command({cmd:"git worktree list --porcelain; git log --all --oneline --decorate --grep='[Dd]oppler' -20","workdir":"/Users/cooper/Projects/bundjil","yield_time_ms":10000,"max_output_tokens":20000}),
  tools.exec_command({cmd:"git worktree list --porcelain; git log --all --oneline --decorate --grep='[Dd]oppler' -20","workdir":"/Users/cooper/Projects/site","yield_time_ms":10000,"max_output_tokens":20000})
]); text("BUNDJIL\n"+out[0].output+"\nSITE\n"+out[1].output);

